mapper.select:
SELECT FROM TB_SCHDL S JOIN TB_TEAM TM ON TM.TEAM_SN = S.TEAM_SN LEFT JOIN TB_BID_PBANC P ON P.PBANC_SN = S.PBANC_SN WHERE S.AUTO_REG_YN = 'N' AND S.SCHDL_BGNG_DT >= TO_DATE(#{from}, 'YYYY-MM-DD') AND S.SCHDL_BGNG_DT < TO_DATE(#{to}, 'YYYY-MM-DD') + 1
AND S.TEAM_SN = #{teamSn}
AND S.PBANC_SN IN (SELECT M.PBANC_SN FROM TB_PRP_TMMBR M WHERE M.USER_ID = #{memberId})
AND S.PBANC_SN = #{pbancSn}
ORDER BY S.SCHDL_BGNG_DT, S.SCHDL_SN
